/**
 * Core type contracts and definitions for Shavin Blocks and AST Trees.
 */

export type BlockCategory =
  | "hero"
  | "features"
  | "pricing"
  | "auth"
  | "metrics"
  | "testimonials"
  | "navigation"
  | "footer"
  | "cta"
  | "content"
  | "dashboard"
  | "commerce";

export type BlockTier = "system" | "community" | "pro";

/**
 * Origin declares which half of a block template was authored (canonical)
 * and which is auto-generated (derived). This is the core of the
 * bidirectional model:
 *
 *  - `"rawCode"` — rawCode was hand-written (community/contributor flow);
 *    the tree is auto-generated by parsing the rawCode.
 *  - `"tree"`    — tree was authored in Studio; rawCode is auto-generated
 *    by serializing the tree.
 *  - `"both"`    — both halves have been reconciled and are in sync;
 *    either can serve as source for the other (post-backfill end state).
 *
 * When origin is "rawCode" and the parser encounters a component not in
 * the DS manifest, it emits a RawHTML node with a warning instead of
 * silently dropping it.
 */
export type BlockOrigin = "rawCode" | "tree" | "both";

export type BlockPropType =
  | "string"
  | "number"
  | "boolean"
  | "select"
  | "color"
  | "icon"
  | "spacing"
  | "radius";

export interface BlockPropDefinition {
  name: string;
  type: BlockPropType;
  label?: string;
  description?: string;
  defaultValue?: string | number | boolean;
  options?: string[] | { label: string; value: string }[];
  category?: "layout" | "appearance" | "typography" | "content" | "advanced";
}

export interface BlockNode {
  id: string;
  type: string;
  props: Record<string, string | number | boolean>;
  children?: BlockNode[];
  parentId?: string | null;
  text?: string;
}

export interface BlockTemplate {
  name: string;
  slug: string;
  description: string;
  category: BlockCategory;
  tier: BlockTier;
  /** Which half is canonical (authored) vs derived (auto-generated). */
  origin?: BlockOrigin;
  dependencies: string[];
  tags: string[];
  rawCode: string;
  tree?: BlockNode[];
  previewUrl?: string;
  thumbnailUrl?: string;
  author?: string;
  version?: string;
}

export interface SpatialBounds {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface SpatialFrame {
  id: string;
  title: string;
  bounds: SpatialBounds;
  presetDevice?: "block" | "desktop" | "tablet" | "mobile";
  rootNodes: BlockNode[];
  themeScope?: {
    accentColor?: string;
    grayColor?: string;
    radius?: string;
    scaling?: number;
    panelBackground?: "solid" | "translucent";
  };
}

export interface BlockProject {
  schemaVersion: number;
  id: string;
  name: string;
  frames: SpatialFrame[];
  viewport: {
    x: number;
    y: number;
    zoom: number;
  };
  updatedAt: string;
}
